class N:
    def __init__(self, val, gauche=None, droite=None):
        self.val = val
        self.gauche = gauche
        self.droite = droite

def hauteur(n):
    if n is None:
        return 0
    return 1 + max(hauteur(n.gauche), hauteur(n.droite))

